  "battle_interface_schema": {
    "description": "Schema for displaying card information during a Burst Duel. The system will output this information within <Card information> tags whenever a card is played or its information is relevant.",
    "card_types": {
      "servant": {
        "display_format": [
          "**【{card_name}】 ({rarity})**",
          "**属性：{attribute}**",
          "**等级：{level}**",
          "**种族：{race}**",
          "**攻击力：{atk} / 守备力：{def}**",
          "**效果：{effect_description}**"
        ],
        "example": {
          "card_name": "宝石骑士·青玉",
          "rarity": "N级",
          "attribute": "水",
          "level": "4",
          "race": "水族",
          "atk": 0,
          "def": 2200,
          "effect_description": "这张卡只要在场上表侧表示存在，1回合1次，可以变成里侧守备表示。这张卡反转时，可以选择对方场上1张咒术·道具卡破坏。"
        }
      },
      "spell": {
        "display_format": [
          "**【{card_name}】 ({rarity})**",
          "**类型：{spell_type}咒术**",
          "**效果：{effect_description}**"
        ],
        "example": {
          "card_name": "融合",
          "rarity": "R级",
          "spell_type": "通常",
          "effect_description": "从自己的手卡·场上把融合从者卡决定的融合素材从者送去墓地，把那1只融合从者从额外卡组融合召唤。"
        }
      },
      "item": {
        "display_format": [
          "**【{card_name}】 ({rarity})**",
          "**类型：{item_type}道具**",
          "**效果：{effect_description}**"
        ],
        "example_continuous": {
          "card_name": "光之护封剑",
          "rarity": "SR级",
          "item_type": "永续",
          "effect_description": "对方场上的从者不能攻击宣言。这张卡在自己准备阶段3次后破坏。"
        },
        "example_equip": {
          "card_name": "恶魔之斧",
          "rarity": "R级",
          "item_type": "装备",
          "effect_description": "装备从者的攻击力上升1000点。"
        }
      },
      "field": {
        "display_format": [
          "**【{card_name}】 ({rarity})**",
          "**类型：结界**",
          "**效果：{effect_description}**"
        ],
        "example": {
          "card_name": "山",
          "rarity": "R级",
          "effect_description": "场上表侧表示存在的龙族·鸟兽族·雷族从者的攻击力·守备力上升200点。"
        }
      }
    }
  }
}

